#include <iostream>
#include <vector>
using namespace std;

void merge_subarrays(vector<int>& array, int left, int mid, int right) {
    int n_left = mid - left + 1;
    int n_right = right - mid;
    vector<int> leftPart(n_left), rightPart(n_right);
    for (int i = 0; i < n_left; ++i) leftPart[i] = array[left + i];
    for (int j = 0; j < n_right; ++j) rightPart[j] = array[mid + 1 + j];
    int i = 0, j = 0, k = left;
    while (i < n_left && j < n_right) {
        if (leftPart[i] <= rightPart[j]) {
            array[k++] = leftPart[i++];
        } else {
            array[k++] = rightPart[j++];
        }
    }
    while (i < n_left) array[k++] = leftPart[i++];
    while (j < n_right) array[k++] = rightPart[j++];
}

void sortArray(vector<int>& array, int start, int end) {
    if (start < end) {
        int mid = start + (end - start) / 2;
        sortArray(array, start, mid);
        sortArray(array, mid + 1, end);
        merge_subarrays(array, start, mid, end);
    }
}

int main() {
    int n;
    cin >> n;
    vector<int> v(n);
    for (int i = 0; i < n; ++i) cin >> v[i];
    sortArray(v, 0, n - 1);
    if (n == 1) {
        cout << v[0] << "\n";
    } else {
        int midIdx = n / 2;
        cout << v[midIdx] << "\n";
    }
    return 0;
}
